async function openOrFocusWindow(url) {
  const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true })
  const existingWindow = windows.find((client) => client.url === url) ?? windows.find((client) => "navigate" in client)

  if (existingWindow) {
    try {
      const focusedWindow = await existingWindow.focus()
      return focusedWindow.url === url ? focusedWindow : await focusedWindow.navigate(url)
    } catch {
      // Uncontrolled windows can't be navigated from here, so open a fresh one
    }
  }

  return self.clients.openWindow(url)
}

